def install() -> None:
    from jarvis.i18n import EXACT
    for source, translations in ROWS.items():
        EXACT[source] = dict(zip(LANGS, translations))


def model_text(message: str, language: str) -> str:
    if language not in LANGS:
        return message
    index = LANGS.index(language)
    for source, translations in ROWS.items():
        if source == message:
            return translations[index]
        if '{' not in source:
            continue
        pattern = ''
        for literal, name, _, _ in string.Formatter().parse(source):
            pattern += re.escape(literal)
            if name:
                pattern += '(?P<' + name + '>.+?)'
        match = re.fullmatch(pattern, message, re.S)
        if match:
            return translations[index].format(**match.groupdict())
    return message
